function cast(a,q,mode='forward',aim=null){if(a.dead||a.frozen>time||ended)return;const spell=compile(q);let dir=aim?{x:aim.x-a.x,z:aim.z-a.z}:{x:a.team===0?1:-1,z:0};const l=Math.hypot(dir.x,dir.z)||1;dir.x/=l;dir.z/=l;a.g.rotation.y=Math.atan2(dir.x,dir.z);a.orb.material=mat(spell.color,{emissive:spell.color,emissiveIntensity:2});
 if(mode==='self'){terrainImpact(a.x,a.z,spell.primary,2,spell.power*.45);if(spell.counts.life){const heal=100+spell.power*55;a.hp=Math.min(a.maxHp,a.hp+heal);floating(a,'+'+heal,'#afd780');a.burning=0;pulse(a.x,a.z,'#a2dc7b',2);}else if(spell.counts.shield){a.ward=time+5;a.wardElement=Object.keys(spell.counts).find(e=>e!=='shield')||'shield';pulse(a.x,a.z,spell.color,2);}else{hurt(a,spell.damage,a);pulse(a.x,a.z,spell.color,2);}return;}
 if(mode==='area'){terrainImpact(a.x,a.z,spell.primary,5,spell.power*.55);pulse(a.x,a.z,spell.color,6);for(const b of agents)if(!b.dead&&b!==a&&dist(a,b)<6){if(spell.counts.life&&b.team===a.team)b.hp=Math.min(b.maxHp,b.hp+120);else if(b.team!==a.team)hurt(b,spell.damage,a);}return;}
 if(spell.type==='shield'||spell.type==='wall'){const x=a.x+dir.x*3,z=a.z+dir.z*3,w=makeWall(x,z,a.team,spell.type,spell.color);w.g.rotation.y=Math.atan2(dir.x,dir.z);walls.push(w);if(walls.length>20)disposeWall(walls.shift());terrainImpact(x,z,spell.primary,2,spell.power*.45);return;}
 if(spell.type==='heal'){const b=targetAlong(a,dir,18,b=>b.team===a.team)||a;b.hp=Math.min(b.maxHp,b.hp+90+spell.power*30);effectLine(a,b,spell.color,.12,.25);terrainTrace(a,b,'life');terrainImpact(b.x,b.z,'life',2,spell.power*.4);return;}
 if(spell.type==='projectile'){const speed=spell.counts.earth?35:44,m=projectileMesh(spell.color,Boolean(spell.counts.earth),a.x,a.z);projectiles.push({m,x:a.x,z:a.z,dir,a,spell,life:1.55,speed,trailTick:0});if(net.role==='host')sendNet({type:'effect',effect:{kind:'projectile-launch',x:a.x,z:a.z,dx:dir.x,dz:dir.z,color:spell.color,speed,rocky:Boolean(spell.counts.earth)}});return;}
 if(spell.type==='beam'){let target=targetAlong(a,dir,24,b=>b.team!==a.team);let end=target||{x:a.x+dir.x*24,z:a.z+dir.z*24};const scenery=destruction.firstCollision(a,dir,dist(a,end));if(scenery){end=scenery;target=null;}const block=walls.find(w=>w.team!==a.team&&((w.x-a.x)*dir.x+(w.z-a.z)*dir.z)>0&&Math.abs((w.x-a.x)*dir.z-(w.z-a.z)*dir.x)<3&&dist(a,w)<dist(a,end));if(block){end=block;block.hp-=40;}else if(target)hurt(target,spell.damage,a);effectLine(a,end,spell.color,.2,.22);effectLine(a,end,'#fff3dc',.017,.17);terrainTrace(a,end,spell.primary);terrainImpact(end.x,end.z,spell.primary,2,spell.power*.7);if(!target&&!block)for(const s of structures)if(!s.dead&&s.team!==a.team&&dist(s,end)<5)damageStructure(s,35,a);return;}
 if(spell.type==='lightning'){let targets=agents.filter(b=>!b.dead&&b.team!==a.team&&dist(a,b)<17).sort((b,c)=>dist(b,aim||a)-dist(c,aim||a)).slice(0,3);let from=a;for(const b of targets){const mid={x:(from.x+b.x)/2+rand(-1,1),z:(from.z+b.z)/2+rand(-1,1),y:2.5};effectLine(from,mid,spell.color,.09,.2);effectLine(mid,b,spell.color,.09,.2);terrainTrace(from,b,'lightning');terrainImpact(b.x,b.z,'lightning',1.6,spell.power*.5);hurt(b,spell.damage,a);from=b;}if(!targets.length){const end={x:a.x+dir.x*12,z:a.z+dir.z*12};effectLine(a,end,spell.color,.08,.2);terrainTrace(a,end,'lightning');terrainImpact(end.x,end.z,'lightning',1.5,spell.power*.5);}return;}
 if(spell.type==='spray'){const end={x:a.x+dir.x*7,z:a.z+dir.z*7};for(let i=0;i<7;i++){const spread=rand(-.36,.36),dx=dir.x*Math.cos(spread)-dir.z*Math.sin(spread),dz=dir.z*Math.cos(spread)+dir.x*Math.sin(spread);destruction.burst(a.x+dx*rand(2,7),a.z+dz*rand(2,7),spell.color,2,1.2);}effectLine(a,end,spell.color,.12,.14);terrainTrace(a,end,spell.primary);terrainImpact(end.x,end.z,spell.primary,3.4,spell.power*.55);for(const b of agents){if(b.dead||b.team===a.team)continue;const d=dist(a,b);if(d<10&&((b.x-a.x)*dir.x+(b.z-a.z)*dir.z)/(d||1)>.78){hurt(b,spell.damage,a);if(spell.primary==='water'){b.x+=dir.x*.4;b.z+=dir.z*.4;}}}for(const s of structures)if(!s.dead&&s.team!==a.team&&dist(a,s)<9&&((s.x-a.x)*dir.x+(s.z-a.z)*dir.z)>0)damageStructure(s,18,a);return;}
 terrainTrace(a,{x:a.x+dir.x*5,z:a.z+dir.z*5},spell.primary);terrainImpact(a.x+dir.x*5,a.z+dir.z*5,spell.primary,2,spell.power*.4);pulse(a.x+dir.x*2,a.z+dir.z*2,'#cee3ce',2);for(const b of agents)if(!b.dead&&b.team!==a.team&&dist(a,b)<5){b.x+=dir.x*1.8;b.z+=dir.z*1.8;}
}
function moveAgent(a,tx,tz,dt){if(a.frozen>time)return;const d=Math.hypot(tx-a.x,tz-a.z);if(d<.25)return;let speed=((a===player||net.role==='host'&&a.id===8)?11.8:7.2)*(a.chill>15?.65:1);if(a.burning>time)speed*=1.05;let dx=(tx-a.x)/d,dz=(tz-a.z)/d;for(const b of agents)if(b!==a&&!b.dead){const dd=dist(a,b);if(dd<1.25&&dd>.01){dx+=(a.x-b.x)/dd*.5;dz+=(a.z-b.z)/dd*.5;}}const nx=clamp(a.x+dx*speed*dt,-60,60),nz=clamp(a.z+dz*speed*dt,-39,39);if(Math.abs(nx)<3.8&&!lanes.some(z=>Math.abs(z-nz)<2.7)){const bridge=lanes.reduce((best,z)=>Math.abs(z-nz)<Math.abs(best-nz)?z:best,0);a.z+=Math.sign(bridge-a.z)*speed*dt;}else if(!walls.some(w=>dist({x:nx,z:nz},w)<2&&w.team!==a.team)&&!destruction.blocks(nx,nz)){a.x=nx;a.z=nz;}a.g.rotation.y=Math.atan2(dx,dz);a.body.rotation.z=Math.sin(time*11+a.id)*.07;a.feet[0].position.z=Math.sin(time*11+a.id)*.2;a.feet[1].position.z=-Math.sin(time*11+a.id)*.2;}
function dashAgent(a,target){if(a.dead||a.frozen>time||a.dashReady>time||ended||!target||!Number.isFinite(target.x)||!Number.isFinite(target.z))return false;const dx=target.x-a.x,dz=target.z-a.z,len=Math.hypot(dx,dz);if(len<.4)return false;const from={x:a.x,z:a.z},ux=dx/len,uz=dz/len;for(let i=0;i<7;i++){const nx=clamp(a.x+ux*1.05,-60,60),nz=clamp(a.z+uz*1.05,-39,39);if(Math.abs(nx)<3.8&&!lanes.some(z=>Math.abs(z-nz)<2.7)||walls.some(w=>dist({x:nx,z:nz},w)<2&&w.team!==a.team)||destruction.blocks(nx,nz))break;a.x=nx;a.z=nz;}if(dist(from,a)<.4)return false;a.dashReady=time+2.2;a.target=null;if(a===player)selection.visible=false;terrainTrace(from,a,'arcane');terrainImpact(a.x,a.z,'arcane',1.5,.45);burst(a.x,a.z,teamColors[a.team],14,1.3);return true;}
const botCombos=[['fire','fire'],['earth','fire'],['arcane','lightning'],['water'],['cold','cold'],['lightning'],['earth','earth'],['arcane']];
function botUpdate(a,dt){const enemies=agents.filter(b=>!b.dead&&b.team!==a.team);let enemy=enemies.sort((b,c)=>dist(a,b)-dist(a,c))[0];let target=enemy;const obj=shrines[a.aiMode%2];if(!enemy||dist(a,enemy)>20){if(a.aiMode<2&&obj.owner!==a.team)target=obj;else target=structures.find(s=>s.team!==a.team&&!s.dead&&!s.core&&Math.abs(s.z-a.lane)<1)||structures.find(s=>s.team!==a.team&&!s.dead&&s.core);}
 if(!target)return;const d=dist(a,target);if(a.hp<260&&a.cd<=0){cast(a,['life','life'],'self');a.cd=1.1;moveAgent(a,a.x+(a.team===0?-8:8),a.z,dt);return;}
 const range=target.hp!==undefined?10:1.5;if(d>range)moveAgent(a,target.x,target.z,dt);else if(target.id!==undefined&&d<5)moveAgent(a,a.x+(a.x-target.x)*2,a.z+(a.z-target.z)*2,dt);
 a.cd-=dt;if(a.cd<=0&&enemy&&dist(a,enemy)<19){cast(a,botCombos[a.id%botCombos.length],'forward',enemy);a.cd=rand(.58,1.05);if(rng()<.08)cast(a,['shield'],'self');}else if(a.cd<=0&&target.maxHp>1000&&d<13){cast(a,['earth','fire'],'forward',target);a.cd=.95;}}
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),ground=new THREE.Plane(new THREE.Vector3(0,1,0),0),aim=new THREE.Vector3();let mouse={x:0,z:0};
function worldAt(e){pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);return raycaster.ray.intersectPlane(ground,aim);}
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const p=worldAt(e);if(p)mouse={x:p.x,z:p.z};});
