canvas.addEventListener('pointerdown',e=>{e.preventDefault();if(e.pointerType==='touch')document.body.classList.add('touch-ui');if(!playing){if(net.mode!=='local')return;start();}if(paused||ended)return;const p=worldAt(e);if(p)mouse={x:p.x,z:p.z};if(e.button===0){if(e.shiftKey||e.detail>=2)playerDash(mouse);else{player.target={x:clamp(mouse.x,-60,60),z:clamp(mouse.z,-39,39)};if(net.role==='guest')sendNet({type:'input',input:{kind:'move',...player.target}});selection.position.set(player.target.x,.13,player.target.z);selection.visible=true;}}else if(e.button===2){rightHeld=true;areaHeld=e.shiftKey;playerCast();}else if(e.button===1)playerCast('self');});
