 const pad={element,knob,pointer:null,used:false};pads.push(pad);
 function update(e){const b=element.getBoundingClientRect(),radius=b.width*.34;const v=padVector(e.clientX-b.left-b.width/2,e.clientY-b.top-b.height/2,radius);knob.style.transform=`translate(calc(-50% + ${v.x*radius}px),calc(-50% + ${v.y*radius}px))`;
  if(kind==='move'){touch.move=v;player.target=null;selection.visible=false;}else{touch.aiming=Math.hypot(v.x,v.y)>.01;if(touch.aiming){touch.aim=v;pad.used=true;}}
 }
