$('quickShield').addEventListener('pointerdown',e=>{e.preventDefault();quickShield();});
$('dashBtn').addEventListener('pointerdown',e=>{e.preventDefault();const dir=touch.aiming?screenToWorld(touch.aim.x,touch.aim.y):{x:player.team===0?1:-1,z:0};playerDash({x:player.x+dir.x*15,z:player.z+dir.z*15});});
$('zoomIn').onclick=()=>{zoom=clamp(zoom-.15,.65,1.55);resize();};
$('zoomOut').onclick=()=>{zoom=clamp(zoom+.15,.65,1.55);resize();};
