window.addEventListener('resize',resetTouch);
function renderQueue(){const spell=compile(queue);$('queue').innerHTML=Array.from({length:5},(_,i)=>{const e=ELEMENTS[queue[i]];return `<div class="slot ${e?'filled':'empty'}" ${e?`style="--el:${e.color}" title="${e.name}"`:''}>${e?e.symbol:''}</div>`;}).join('');$('spellName').textContent=queue.length?spell.name:'Соберите комбинацию';}
function addElement(id){if(queue.length>=5){notify('В комбинации максимум пять элементов');return;}queue.push(id);renderQueue();}
for(const[id,e]of Object.entries(ELEMENTS)){const b=document.createElement('button');b.className='element';b.style.setProperty('--el',e.color);b.title=`${e.name} · ${e.key}`;b.setAttribute('aria-label',`${e.name}, клавиша ${e.key}`);b.innerHTML=`<kbd>${e.key}</kbd><span class="symbol">${e.symbol}</span><span class="el-name">${e.name.toUpperCase()}</span>`;let lastTouch=-Infinity;b.addEventListener('pointerdown',ev=>{if(ev.pointerType!=='touch')return;ev.preventDefault();lastTouch=performance.now();addElement(id);});b.onclick=()=>{if(performance.now()-lastTouch>500)addElement(id);};$('elements').appendChild(b);}
for(let i=0;i<16;i++){const s=document.createElement('span');s.textContent='♟';s.title=names[i];$('teamStrip').appendChild(s);}
window.addEventListener('keydown',e=>{if(e.code==='Escape'){if($('help').open){$('help').close();return;}if(net.mode==='local'&&playing&&!ended)setPaused(!paused);return;}if($('help').open||$('result').open||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;const id=Object.keys(ELEMENTS).find(k=>'Key'+ELEMENTS[k].key===e.code);if(id&&!e.repeat){e.preventDefault();addElement(id);}if(e.code==='Backspace'){e.preventDefault();queue.pop();renderQueue();}if(e.code==='Space'){e.preventDefault();if(e.shiftKey)playerDash();else quickShield();}});
$('clearBtn').onclick=()=>{queue=[];renderQueue();};
