$('playBtn').onclick=()=>{if(net.ws)net.ws.close();net.mode='local';net.role=null;start();};$('watchBtn').onclick=()=>{$('intro').classList.add('hidden');notify(document.body.classList.contains('touch-ui')?'Коснитесь арены, чтобы вступить в бой.':'Колесо мыши — масштаб. Нажмите на арену, чтобы вступить в бой.');};
function showHelp(){resetTouch();$('help').showModal();rightHeld=false;}
$('helpBtn').onclick=showHelp;$('controlsLink').onclick=showHelp;$('closeHelp').onclick=()=>$('help').close();$('helpPlay').onclick=()=>{$('help').close();if(net.mode==='local')start();};
function setPaused(value){if(net.mode!=='local')return;paused=value;if(value){rightHeld=false;resetTouch();}$('pauseBtn').textContent=paused?'▶':'II';$('pauseBtn').title=paused?'Продолжить':'Пауза';if(paused)notify('Пауза — нажмите Esc или ▷');else{$('message').classList.remove('visible');last=performance.now();}}
$('pauseBtn').onclick=()=>setPaused(!paused);$('cameraBtn').onclick=()=>{cameraTarget.set(player.x,0,player.z);zoom=1;resize();};$('restartBtn').onclick=()=>location.reload();
function finish(team){if(ended)return;winnerTeam=team;ended=true;rightHeld=false;resetTouch();$('resultTitle').textContent=team===0?'Победа Лазурного ордена':'Победа Багрового ковена';$('resultText').textContent=`Счёт ${scores[0]} : ${scores[1]} · Ваш результат: ${player.kills} убийств, ${player.deaths} смертей`;$('result').showModal();if(net.role==='host')sendState();}
function sendState(){if(net.role!=='host')return;sendNet({type:'state',state:{time,scores,ended,winnerTeam,agents:agents.map(a=>({x:a.x,z:a.z,hp:a.hp,dead:a.dead,respawn:a.respawn,wet:a.wet,burning:a.burning,chill:a.chill,frozen:a.frozen,ward:a.ward,wardElement:a.wardElement,kills:a.kills,deaths:a.deaths,dashReady:a.dashReady,rotation:a.g.rotation.y})),structures:structures.map(s=>({hp:s.hp,dead:s.dead})),shrines:shrines.map(s=>({owner:s.owner,progress:s.progress})),walls:walls.map(w=>({id:w.id,x:w.x,z:w.z,team:w.team,type:w.type,color:w.color,life:w.life,hp:w.hp,rotation:w.g.rotation.y})),terrain:destruction.snapshot()}});}
