 state.agents.forEach((v,i)=>{const a=agents[i],wasDead=a.dead;for(const k of ['x','z','hp','dead','respawn','wet','burning','chill','frozen','ward','wardElement','kills','deaths','dashReady'])a[k]=v[k];a.g.position.set(a.x,0,a.z);a.g.rotation.y=v.rotation;a.g.visible=!a.dead;a.bar.group.quaternion.copy(camera.quaternion);a.bar.fill.scale.x=a.hp/a.maxHp;a.bar.fill.position.x=-(1-a.hp/a.maxHp)*a.bar.width/2;a.marker.material.color.set(a===player?'#e6d599':teamColors[a.team]);if(a===player&&a.dead&&!wasDead)$('respawn').classList.remove('hidden');if(a===player&&!a.dead&&wasDead)$('respawn').classList.add('hidden');});
