function guestUpdate(dt,now){castTimer=Math.max(0,castTimer-dt);if(showMessageUntil<time)$('message').classList.remove('visible');if(touch.aiming){const direction=screenToWorld(touch.aim.x,touch.aim.y);mouse={x:player.x+direction.x*15,z:player.z+direction.z*15};}if(touch.action)playerCast(touch.action);else if(touch.aiming)playerCast('forward');else if(rightHeld)playerCast();if(now-net.lastInput>=100){sendNet({type:'input',input:{kind:'pad',x:touch.move.x,y:touch.move.y}});net.lastInput=now;}}
function frame(now){requestAnimationFrame(frame);const elapsed=Math.max(0,Math.min((now-last)/1000,.2)),dt=Math.min(elapsed,.05);last=now;const active=playing&&!paused&&!ended&&(net.mode==='match'||!$('help').open);if(active){if(net.role==='guest')guestUpdate(dt,now);else{accumulator+=elapsed;while(accumulator>=1/60){update(1/60);accumulator-=1/60;}if(net.role==='host'){for(const [slot,timer] of net.remoteCastTimers)net.remoteCastTimers.set(slot,Math.max(0,timer-elapsed));if(now-net.lastState>=50){sendState();net.lastState=now;}}}visualUpdate(dt);}else accumulator=0;if(playing&&!player.dead)cameraTarget.lerp(new THREE.Vector3(player.x,0,player.z),1-Math.exp(-dt*2.5));else if(!playing)cameraTarget.lerp(new THREE.Vector3(-3,0,0),.01);cameraShake=Math.max(0,cameraShake-dt*1.5);camera.position.set(cameraTarget.x+43+(Math.random()-.5)*cameraShake,70,cameraTarget.z+51+(Math.random()-.5)*cameraShake);camera.lookAt(cameraTarget.x,0,cameraTarget.z);renderer.render(scene,camera);uiTimer+=dt;if(uiTimer>.1){uiTimer=0;updateUI();}}
